task: { id: string; title: string; status: string; description: string | null; duration_days: number | null; materials: string[] | null; job_id: string | null; job_name: string | null; job_status: string | null; worker_name: string | null; assignee_worker_id: string | null; start_date: string | null; due_date: string | null; active_today: boolean; active_tomorrow: boolean; overdue: boolean; days_overdue: number; at_risk: boolean; risk_blocked: boolean; risk_late_start: boolean; risk_due_soon: boolean; risk_late_dependency: boolean; risk_paused_job: boolean; late_dependency_titles: string[]; depends_on_titles: string[]; confirmation_state?: string | null; confirmed_at?: string | null; last_reminder_at?: string | null; proof_count?: number | null };
