dtsPropsFor.Button:
/** THE RULE: at most one `primary` per screen. Three solid orange buttons force the manager to read all three; one means he just taps. */
variant?: 'primary' | 'secondary' | 'tertiary' | 'destructive';
/** 44px / 48px / 56px. The design target is a man in work gloves, not a mouse pointer. */
size?: 'sm' | 'md' | 'lg';
/** Swaps in a spinner while KEEPING the label in the tree, so the button never changes width under the thumb that just tapped it. Also sets disabled and aria-busy. */
loading?: boolean;
fullWidth?: boolean;
icon?: React.ReactNode;
children?: React.ReactNode;
disabled?: boolean;
/** Defaults to 'button'. An unspecified type inside a <form> submits it per the HTML spec, so a bare Cancelar button would silently submit. */
type?: 'button' | 'submit' | 'reset';
onClick?: React.MouseEventHandler<HTMLButtonElement>;
/** NOTE: `className` is deliberately absent from this type. A component that accepts arbitrary classes becomes a sixteenth variant within a month; if you need a new look, add a variant rather than reaching for a class. */

dtsPropsFor.ButtonLink:
href: string;
/** Defaults to 'secondary' here, unlike Button — a link that looks like the page's one primary action usually is not it. */
variant?: 'primary' | 'secondary' | 'tertiary' | 'destructive';
size?: 'sm' | 'md' | 'lg';
fullWidth?: boolean;
icon?: React.ReactNode;
children?: React.ReactNode;
/** A plain <a>, never next/link: @capo/ui is shared with apps/operator and must not depend on a router. A same-origin href is handled by the App Router anyway. */

dtsPropsFor.IconButton:
/** Spoken by a screen reader. REQUIRED, and that is a design decision enforced by the compiler — an unlabelled icon button is invisible to a blind user. */
label: string;
icon: React.ReactNode;
/** Defaults to 'tertiary'. */
variant?: 'primary' | 'secondary' | 'tertiary' | 'destructive';
/** Square: 44 / 48 / 56px. */
size?: 'sm' | 'md' | 'lg';
disabled?: boolean;
onClick?: React.MouseEventHandler<HTMLButtonElement>;

dtsPropsFor.Card:
/** Depth level 1: a hairline border and NO shadow. A shadow is only for something that genuinely floats (a sticky header, a sheet). */
padding?: 'none' | 'sm' | 'md';
/** Use 'none' when the card's children are ListRows — they carry their own padding and must reach the card's edges. */
as?: 'div' | 'section' | 'article';
children: React.ReactNode;

dtsPropsFor.ListRow:
leading?: React.ReactNode;
title: React.ReactNode;
meta?: React.ReactNode;
trailing?: React.ReactNode;
/** When present the whole row becomes a link and gains a chevron. The WHOLE row is the tap target, never just the title — 56px minimum. */
href?: string;
/** Turns the title red. For a row that is overdue or failing, not for a delete affordance. */
danger?: boolean;

dtsPropsFor.Field:
/** Must be unique on the page — it wires label, hint and error to the control. */
id: string;
label: string;
hint?: string;
/** Rendered with role="alert", so a screen reader announces it the moment it appears. Suppresses `hint` while set. */
error?: string;
required?: boolean;
/** A RENDER PROP, not a node: the control cannot be rendered without receiving the ids and aria-* it must carry, which is what makes the wiring impossible to forget. Spread it onto the control: {a11y => <Input {...a11y} />} */
children: (a11y: { id: string; 'aria-describedby'?: string; 'aria-invalid'?: true; required?: boolean }) => React.ReactNode;

dtsPropsFor.Input:
/** Every native <input> prop EXCEPT className. Intended to be spread with a Field's render-prop argument: {a11y => <Input {...a11y} placeholder="Casa de Paco" />} */
type?: string;
placeholder?: string;
defaultValue?: string | number;
value?: string | number;
disabled?: boolean;
required?: boolean;
id?: string;
name?: string;
onChange?: React.ChangeEventHandler<HTMLInputElement>;

dtsPropsFor.Textarea:
/** Every native <textarea> prop EXCEPT className. Min height 6rem, vertically resizable. */
rows?: number;
placeholder?: string;
defaultValue?: string;
value?: string;
disabled?: boolean;
required?: boolean;
id?: string;
name?: string;
onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;

dtsPropsFor.Select:
/** A native <select> on purpose: it works offline, matches the phone's own picker, and handles keyboards correctly. Pass <option> children. */
children?: React.ReactNode;
defaultValue?: string;
value?: string;
disabled?: boolean;
required?: boolean;
id?: string;
name?: string;
onChange?: React.ChangeEventHandler<HTMLSelectElement>;

dtsPropsFor.Badge:
/** 'review' is violet deliberately: a completion claim awaiting the manager is a decision to make, not a problem to fix. 'danger' owns "wrong". */
tone?: 'neutral' | 'info' | 'warn' | 'danger' | 'success' | 'brand' | 'review';
strikethrough?: boolean;
/** A badge is read as a SHAPE, not a sentence — one or two words, rendered 11px uppercase. */
children: React.ReactNode;

dtsPropsFor.Banner:
/** Uses the -solid tokens, which are IDENTICAL in both themes: a danger banner is a fixed signal colour, not a themed surface. 'neutral' is the deliberate exception and follows the theme. */
tone?: 'neutral' | 'info' | 'warn' | 'danger' | 'success' | 'brand' | 'review';
/** Makes the whole strip a link. */
href?: string;
icon?: React.ReactNode;
children: React.ReactNode;
/** LAYOUT CONSTRAINT: keep a Banner a SIBLING of the app's overflow-hidden content column, never a child of it — a child gets clipped. */

dtsPropsFor.Skeleton:
/** Shaped like the content that is coming, not a generic grey bar — a skeleton matching the eventual layout is what stops the page jumping when data lands. */
variant?: 'text' | 'title' | 'row' | 'card';
/** How many to stack. */
count?: number;

dtsPropsFor.AppBar:
title: string;
subtitle?: string;
/** An explicit destination, never router.back(): browser history can lead out of the app entirely. Travels WITH backLabel — the compiler requires both or neither. */
backHref?: string;
/** Spoken by a screen reader. Capo speaks three languages, so the caller passes an already-translated string rather than this defaulting to "Back". */
backLabel?: string;
/** Trailing slot, usually an IconButton. */
action?: React.ReactNode;

dtsPropsFor.Sheet:
open: boolean;
onClose: () => void;
/** Titles the dialog for a screen reader as well as the eye. */
title: string;
children: React.ReactNode;
/** Handles what four hand-rolled sheets did not: Escape closes, focus enters and is trapped, the page behind does not scroll, and it slides rather than teleports. Renders nothing until after the first client commit (it portals to document.body). */

dtsPropsFor.SegmentedControl:
/** The radio group name — must be unique per control on the page. */
name: string;
/** Spoken to a screen reader as the question these options answer. */
legend: string;
/** Sets the INITIAL selection only: it is read once into defaultChecked, so changing it after mount will not move the pill. To force a selection, remount with a new `key`. */
value: string;
options: { value: string; label: string }[];
/** Only ENHANCES the native radios; it never replaces them. They select and save from plain HTML before any JavaScript runs, which is what a cold PWA on a slow phone depends on. */
onChange?: (value: string) => void;

dtsPropsFor.TabBar:
/** The five bottom-nav destinations, labelled from the catalog in this locale. */
locale: 'pt-PT' | 'es-ES' | 'en-US';
/** EVERY TAB CARRIES TWO ICONS (outline + filled), which is an accessibility requirement rather than a flourish: the bar it replaces signalled the active tab by COLOUR ALONE, and orange-versus-grey is a hard pair for the commonest colour-vision deficiency. Reads the active route from usePathname(). */
